<?php
declare(strict_types=1);
require __DIR__.'/music-module-integrity.php';
require dirname(__DIR__).'/includes/music-project-import.php';
$viewer=$owner;
$pdo->exec('UPDATE users SET enabled=1 WHERE id=11');
$pdo->prepare("INSERT INTO artist_catalog_tracks_v181(id,workspace_id,source_track_id,title,audio_path,visibility,is_published) VALUES(10,1,?,'Before import','/uploads/artist-music/1/master.mp3','members',0)")->execute([$source]);
$pdo->exec("CREATE TABLE track_projects(id INTEGER PRIMARY KEY,track_id INTEGER,project_name TEXT,tempo_bpm REAL,time_signature TEXT,imported_at TEXT);CREATE TABLE track_stems(id INTEGER PRIMARY KEY,track_id INTEGER,project_id INTEGER,stem_name TEXT,stem_role TEXT,instrument TEXT,rpp_fx_summary TEXT,duration_seconds REAL,start_offset_seconds REAL,is_active INTEGER,sort_order INTEGER)");
$pdo->prepare("UPDATE tracks SET title='Reviewed title',description='Reviewed production notes',genre='Reggae' WHERE id=?")->execute([$source]);
$before=artist_music_v185_track($pdo,1,10);
$pdo->beginTransaction();music_project_import_sync_catalog($pdo,$source);$pdo->rollBack();
check(artist_music_v185_track($pdo,1,10)['title']==='Before import','Rollback did not preserve catalog metadata');
$pdo->beginTransaction();music_project_import_sync_catalog($pdo,$source);$pdo->commit();
$after=artist_music_v185_track($pdo,1,10);
check($after['title']==='Reviewed title'&&$after['description']==='Reviewed production notes','Reviewed production metadata missed the Music Library');
foreach(['id','source_track_id','audio_path','visibility','is_published','cover_photo_id'] as $field)check($before[$field]===$after[$field],'Import changed catalog '.$field);
$pdo->prepare("INSERT INTO track_projects VALUES(1,?,'Room project',86,'4/4','2026-11-02 12:00:00')")->execute([$source]);
$pdo->prepare("INSERT INTO track_stems VALUES(1,?,1,'Bass','Bass','Electric Bass','ReaEQ',12,3,1,0),(2,?,1,'Old deleted stem','Other','','',0,0,0,1)")->execute([$source,$source]);
$pdo->exec("INSERT INTO tracks(id,workspace_id,owner_user_id,title,lyrics) VALUES(999,2,14,'Foreign secret','');INSERT INTO track_projects VALUES(2,999,'Foreign project',120,'3/4','2026-11-02 13:00:00');INSERT INTO track_stems VALUES(3,999,2,'Secret vocal','Vocal','Voice','',20,0,1,0)");
$context=music_project_import_context($pdo,$owner,'Tell me about my REAPER project');
check(count($context)===1&&str_contains($context[0]['text'],'Electric Bass')&&str_contains($context[0]['text'],'86 BPM'),'Owner cannot discuss imported production metadata');
check(!str_contains(json_encode($context),'Foreign')&&!str_contains(json_encode($context),'Old deleted'),'Foreign or inactive stems leaked into Chat');
check(str_contains($context[0]['text'],'track='.$source),'Studio handoff lost the canonical source ID');
check(music_project_import_context($pdo,$manager,'Studio project')===[],'Removed workspace manager retained project context');
$pdo->exec('UPDATE tracks SET producer_user_id=13 WHERE id='.$source);
check(count(music_project_import_context($pdo,$producer,'Studio project'))===1,'Assigned producer cannot read project context');
$pdo->exec('UPDATE tracks SET producer_user_id=NULL WHERE id='.$source);
check(music_project_import_context($pdo,$producer,'Studio project')===[],'Unassigned producer retained project context');
$n=(int)$pdo->query('SELECT COUNT(*) FROM notifications')->fetchColumn();music_project_import_activity($owner,$source,1,1);music_project_import_activity($owner,$source,1,1);
check((int)$pdo->query('SELECT COUNT(*) FROM notifications')->fetchColumn()===$n+1,'Import activity was missing or duplicated');
check(notification_is_agent_brain_activity($pdo->query('SELECT * FROM notifications ORDER BY id DESC LIMIT 1')->fetch()),'Import notice did not route to Agent Brain');
echo "MUSIC_PROJECT_IMPORT=PASS catalog synchronization, rollback, preserved audio/visibility/IDs, workspace and producer boundaries, active stems and Brain activity\n";
